const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const userMessage = String(body.message || body.chatInput || '').trim();
const q = userMessage.toLowerCase();
const sessionId = String(body.sessionId || 'guest-session').trim();
const timestamp = String(body.timestamp || new Date().toISOString());

const ADMIN_WA = '6285836137886';
const BATCH = {
  batchCode: 'Batch #14',
  statusLabel: 'Open PO Aktif',
  openPoDates: '25 – 30 Nov 2026',
  shoppingRestockDates: '1 – 3 Des 2026',
  shippingEstimate: 'Mulai 5 Des 2026',
  note: 'Item bertanda Ready Stock langsung dikirim H+1 setelah konfirmasi.'
};

const CATALOG = [
  {
    id: 'glow-niacinamide-serum',
    name: 'Aura Skn Brightening Radiance Serum 30ml',
    category: 'Skincare & Kecantikan',
    availability: 'Ready Stock',
    price: 165000,
    variants: ['30ml (Full Size)', '15ml (Travel Size)'],
    keywords: ['serum', 'aura skn', 'niacinamide', 'vitamin c', 'skincare', 'cerah']
  },
  {
    id: 'lumiere-velvet-cushion',
    name: 'Lumiere Matte Velvet Cushion SPF 35',
    category: 'Skincare & Kecantikan',
    availability: 'Open PO',
    price: 235000,
    variants: ['01 Ivory Fair', '02 Warm Beige', '03 Honey Sand'],
    keywords: ['cushion', 'lumiere', 'velvet', 'makeup', 'spf', 'skincare']
  },
  {
    id: 'lumin-gloss-lip-tint',
    name: 'Lumin Glassy Velvet Lip Tint',
    category: 'Skincare & Kecantikan',
    availability: 'Ready Stock',
    price: 118000,
    variants: ['01 Coral Peach', '02 Rosewood Mauve'],
    keywords: ['lip', 'tint', 'liptint', 'lumin', 'bibir', 'makeup']
  },
  {
    id: 'momo-ceremonial-matcha',
    name: 'Momo Ceremonial Grade Matcha Tin 40g',
    category: 'Makanan & Minuman Viral',
    availability: 'Open PO',
    price: 195000,
    variants: ['Kaleng 40g', 'Refill Pouch 80g'],
    keywords: ['matcha', 'momo', 'teh hijau', 'minuman', 'latte']
  },
  {
    id: 'aura-freeze-dried-mango',
    name: 'Aura Freeze-Dried Golden Mango 100g',
    category: 'Makanan & Minuman Viral',
    availability: 'Ready Stock',
    price: 78000,
    variants: ['Original 100g', 'Paket Hemat 3 Pouch'],
    keywords: ['mango', 'mangga', 'snack', 'camilan', 'freeze']
  },
  {
    id: 'cha-thai-artisanal-box',
    name: 'Cha Thai Artisanal Milk Tea (Isi 10 Sachet)',
    category: 'Makanan & Minuman Viral',
    availability: 'Ready Stock',
    price: 89000,
    variants: ['Original Sweet (10 Sachet)', 'Less Sugar (10 Sachet)'],
    keywords: ['thai tea', 'cha thai', 'milk tea', 'teh', 'sachet']
  },
  {
    id: 'aura-herbal-inhaler-set',
    name: 'Aura Eucalyptus Mint Inhaler & Roll-On Set',
    category: 'Kebutuhan Rumah & Gaya Hidup',
    availability: 'Open PO',
    price: 135000,
    variants: ['Set Inhaler + Roll-On', 'Inhaler Only'],
    keywords: ['inhaler', 'roll-on', 'aromaterapi', 'mint', 'eucalyptus', 'minyak']
  },
  {
    id: 'quilted-travel-organizer',
    name: 'Sawadhee Quilted Travel & Cosmetic Pouch',
    category: 'Kebutuhan Rumah & Gaya Hidup',
    availability: 'Ready Stock',
    price: 149000,
    variants: ['Sage Teal', 'Warm Oat'],
    keywords: ['pouch', 'tas', 'organizer', 'travel', 'cosmetic']
  }
];

const SHIPPING_ZONES = [
  { id: 'jawa', name: 'Pulau Jawa', ratePerKg: 14000, estimateDays: '1 – 3 hari kerja', keywords: ['jawa', 'jakarta', 'jabodetabek', 'bandung', 'surabaya', 'semarang', 'yogya', 'malang'] },
  { id: 'sumatera', name: 'Sumatera', ratePerKg: 24000, estimateDays: '2 – 5 hari kerja', keywords: ['sumatera', 'medan', 'palembang', 'lampung', 'padang'] },
  { id: 'bali-nusra', name: 'Bali & Nusa Tenggara', ratePerKg: 26000, estimateDays: '3 – 5 hari kerja', keywords: ['bali', 'denpasar', 'lombok', 'mataram', 'kupang'] },
  { id: 'kalimantan', name: 'Kalimantan', ratePerKg: 34000, estimateDays: '3 – 6 hari kerja', keywords: ['kalimantan', 'balikpapan', 'banjarmasin', 'pontianak'] },
  { id: 'sulawesi', name: 'Sulawesi', ratePerKg: 38000, estimateDays: '4 – 7 hari kerja', keywords: ['sulawesi', 'makassar', 'manado', 'palu', 'kendari'] },
  { id: 'maluku-papua', name: 'Maluku & Papua', ratePerKg: 58000, estimateDays: '5 – 9 hari kerja', keywords: ['maluku', 'papua', 'ambon', 'jayapura', 'sorong'] }
];

const matchedProducts = CATALOG.filter((item) =>
  item.keywords.some((kw) => q.includes(kw)) ||
  (q.includes('ready') && item.availability === 'Ready Stock') ||
  (q.includes('open po') && item.availability === 'Open PO')
);

const matchedZone = SHIPPING_ZONES.find((z) =>
  z.keywords.some((kw) => q.includes(kw))
) || null;

let intent = 'umum';
if (q.includes('batch') || q.includes('jadwal') || q.includes('kapan') || q.includes('kirim')) {
  intent = 'jadwal_batch';
} else if (
  matchedProducts.length > 0 ||
  q.includes('produk') ||
  q.includes('stok') ||
  q.includes('harga') ||
  q.includes('katalog') ||
  q.includes('ready')
) {
  intent = 'cek_produk';
} else if (
  matchedZone !== null ||
  q.includes('ongkir') ||
  q.includes('cod') ||
  q.includes('bayar') ||
  q.includes('transfer') ||
  q.includes('dp') ||
  q.includes('qris')
) {
  intent = 'ongkir_pembayaran';
}

return [{
  json: {
    userMessage,
    sessionId,
    timestamp,
    intent,
    adminWa: ADMIN_WA,
    batch: BATCH,
    matchedProducts,
    matchedZone,
    shippingZones: SHIPPING_ZONES,
    catalogCount: CATALOG.length
  }
}];

const d = $input.first().json;
const b = d.batch;
const waText = encodeURIComponent(`Halo Admin By Sawadhee, saya ingin tanya jadwal ${b.batchCode}: ${d.userMessage}`);

return [{
  json: {
    reply: `Jadwal ${b.batchCode} (${b.statusLabel}):\n• Buka Pre-Order: ${b.openPoDates}\n• Belanja & Restock: ${b.shoppingRestockDates}\n• Estimasi Pengiriman: ${b.shippingEstimate}\n\n${b.note}`,
    intent: d.intent,
    batch: b,
    sessionId: d.sessionId,
    whatsappUrl: `https://wa.me/${d.adminWa}?text=${waText}`,
    receivedAt: new Date().toISOString()
  }
}];

const d = $input.first().json;
const formatRp = (n) => 'Rp ' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const items = d.matchedProducts || [];

let reply = '';
if (items.length > 0) {
  const lines = items.slice(0, 4).map((p, idx) =>
    `${idx + 1}. ${p.name} — ${formatRp(p.price)} (${p.availability})`
  );
  reply = `Berikut produk By Sawadhee yang cocok dengan pertanyaan Anda:\n${lines.join('\n')}\n\nKlik "+ Keranjang" di katalog untuk langsung menghitung subtotal & kirim order ke WhatsApp.`;
} else {
  reply = `Saat ini tersedia ${d.catalogCount} produk kurasi By Sawadhee (Skincare, Makanan & Minuman Viral, serta Kebutuhan Rumah). Item bertanda Ready Stock dikirim H+1, sedangkan Open PO mengikuti jadwal ${d.batch.batchCode}.`;
}

const waText = encodeURIComponent(`Halo Admin By Sawadhee, saya ingin menanyakan stok produk: ${d.userMessage}`);

return [{
  json: {
    reply,
    intent: d.intent,
    batch: d.batch.batchCode,
    matchedProducts: items.map((p) => ({
      id: p.id,
      name: p.name,
      price: p.price,
      availability: p.availability,
      variants: p.variants
    })),
    sessionId: d.sessionId,
    whatsappUrl: `https://wa.me/${d.adminWa}?text=${waText}`,
    receivedAt: new Date().toISOString()
  }
}];

const d = $input.first().json;
const formatRp = (n) => 'Rp ' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');

let ongkirText = '';
if (d.matchedZone) {
  ongkirText = `Estimasi ongkir ke ${d.matchedZone.name}: ${formatRp(d.matchedZone.ratePerKg)}/kg (${d.matchedZone.estimateDays}).`;
} else {
  ongkirText = 'Estimasi ongkir reguler mulai Rp 14.000/kg (Pulau Jawa), Rp 24.000/kg (Sumatera), Rp 26.000/kg (Bali & Nusra), hingga Rp 34.000–58.000/kg (Kalimantan, Sulawesi, Maluku & Papua).';
}

const reply = `${ongkirText}\n\nMetode pembayaran: Transfer Bank, QRIS/E-Wallet (GoPay/OVO), dan COD untuk produk Ready Stock. Khusus item Open PO di atas Rp 300.000 cukup DP 50%.`;
const waText = encodeURIComponent(`Halo Admin By Sawadhee, saya ingin cek ongkir & metode pembayaran: ${d.userMessage}`);

return [{
  json: {
    reply,
    intent: d.intent,
    matchedZone: d.matchedZone,
    paymentMethods: ['Transfer Bank', 'E-Wallet (QRIS / GoPay / OVO)', 'COD (Bayar di Tempat)'],
    sessionId: d.sessionId,
    whatsappUrl: `https://wa.me/${d.adminWa}?text=${waText}`,
    receivedAt: new Date().toISOString()
  }
}];

const d = $input.first().json;
const waText = encodeURIComponent(`Halo Admin By Sawadhee, saya ingin bertanya / titip barang: ${d.userMessage}`);

return [{
  json: {
    reply: `Terima kasih telah menghubungi By Sawadhee! Untuk titip barang di luar katalog atau konsultasi ${d.batch.batchCode}, silakan kirim detail/foto produk langsung ke WhatsApp Admin (${d.adminWa}) agar tim kami segera cek harga & slot belanjanya.`,
    intent: d.intent,
    batch: d.batch.batchCode,
    echoMessage: d.userMessage,
    sessionId: d.sessionId,
    whatsappUrl: `https://wa.me/${d.adminWa}?text=${waText}`,
    receivedAt: new Date().toISOString()
  }
}];
